// Package pacman serves hosted Arch Linux package repositories to pacman.
//
// A repository is laid out the way pacman's "Server = URL/$repo/os/$arch" line
// expects: /repos/{name}/os/{arch}/ holds the package files, their detached
// ".sig" files and the generated "<section>.db" and "<section>.files"
// databases (with signatures). The databases are generated by the metadata
// worker (internal/worker) from the package rows and stored as repository
// metadata; this package only stores uploaded packages and serves files.
package pacman

import (
	"encoding/base64"
	"net/http"
	"net/url"
	"strings"

	"github.com/go-chi/chi/v5"

	"context"

	"github.com/openartifact/openartifact/internal/database/models"
	"github.com/openartifact/openartifact/internal/format/base"
	"github.com/openartifact/openartifact/internal/presign"
	"github.com/openartifact/openartifact/internal/quarantine"
	"github.com/openartifact/openartifact/internal/storage"
	"github.com/openartifact/openartifact/internal/urlparams"
	"github.com/openartifact/openartifact/pkg/logger"
	"github.com/openartifact/openartifact/pkg/pacman"
)

// FormatName is the repository format name.
const FormatName = "pacman"

// How long shared caches may reuse a public repository's responses before
// revalidating. Package files never change under their name.
const (
	databaseMaxAge = 60
	packageMaxAge  = 3600
)

// Regenerator asks for the repository databases to be regenerated.
// *worker.PacmanMetadataWorker implements it (coalesced, never inline).
type Regenerator interface {
	NotifyStale(repoID string)
}

// HTTPStore is the part of the database HTTPHandler needs.
type HTTPStore interface {
	BlobReferenceCount(ctx context.Context, sha256 string) (int, error)
	CreatePacmanPackage(ctx context.Context, pkg *models.PacmanPackage) error
	DecrementStorageUsage(ctx context.Context, repoID string, sizeBytes int64, artifactCount int) error
	DeletePacmanPackage(ctx context.Context, repoID string, id string) error
	GetPacmanPackageByFilename(ctx context.Context, repoID string, filename string) (*models.PacmanPackage, error)
	GetRawArtifact(ctx context.Context, repoID string, path string) (*models.RawArtifact, error)
	GetRepoMetadataByPath(ctx context.Context, repositoryID string, path string) (*models.RepoMetadata, error)
	GetRepositoryByName(ctx context.Context, name string) (*models.Repository, error)
	ListLicensePolicies(ctx context.Context, repoID string) ([]*models.LicensePolicy, error)
	ReserveStorageUsage(ctx context.Context, repoID string, sizeBytes int64, artifactCount int) (bool, error)
	SetPacmanSignature(ctx context.Context, repoID string, id string, signature string, source string, key string) error
	UpsertRawArtifact(ctx context.Context, artifact *models.RawArtifact) error
}

// HTTPHandler serves hosted pacman repositories.
type HTTPHandler struct {
	*base.Handler

	regen Regenerator
	DB    HTTPStore
}

// NewHTTPHandler creates the handler.
func NewHTTPHandler(log *logger.Logger, db HTTPStore, blobStore storage.BlobStore, baseURL string) *HTTPHandler {
	return &HTTPHandler{Handler: base.New(log, db, blobStore, baseURL), DB: db}
}

// SetRegenerator sets the worker that regenerates the databases after an
// upload or delete.
func (h *HTTPHandler) SetRegenerator(r Regenerator) { h.regen = r }

func (h *HTTPHandler) notifyStale(repoID string) {
	if h.regen != nil {
		h.regen.NotifyStale(repoID)
	}
}

// RegisterRepoRoutes registers the pacman routes on the /repos/{name}
// subrouter. The repository public key is served by the shared /public.key
// route. A request for a repository of another format is answered 404.
func (h *HTTPHandler) RegisterRepoRoutes(r chi.Router) {
	r.Get("/os/{arch}/{filename}", h.handleGet)
	r.Put("/os/{arch}/{filename}", h.handlePut)
	r.Delete("/os/{arch}/{filename}", h.handleDelete)
}

// resolveRepo returns the pacman repository named in the URL. When there is
// none it writes the response and returns nil.
func (h *HTTPHandler) resolveRepo(w http.ResponseWriter, r *http.Request) *models.Repository {
	name := urlparams.Vars(r)["name"]

	repo, err := h.ResolveRepo(r.Context(), name)
	if err != nil {
		h.Log.Errorw("failed to resolve repo", "name", name, "error", err)
		http.Error(w, "internal error", http.StatusInternalServerError)

		return nil
	}

	if repo == nil || repo.Format != FormatName {
		http.NotFound(w, r)
		return nil
	}

	return repo
}

// fileParam returns the file name of the URL. The router hands out the raw
// path, in which pacman writes the colon of an epoch as %3A; a name that does
// not decode is returned as is and fails pacman.ClassifyFile.
func fileParam(r *http.Request) string {
	raw := urlparams.Vars(r)["filename"]

	name, err := url.PathUnescape(raw)
	if err != nil {
		return raw
	}

	return name
}

// archOf returns the architecture directory of the URL, or writes a 400.
func archOf(w http.ResponseWriter, r *http.Request) (string, bool) {
	arch := urlparams.Vars(r)["arch"]
	if !pacman.ValidArch(arch) {
		http.Error(w, "invalid architecture", http.StatusBadRequest)
		return "", false
	}

	return arch, true
}

func (h *HTTPHandler) handleGet(w http.ResponseWriter, r *http.Request) {
	filename := fileParam(r)

	kind, doc := pacman.ClassifyFile(filename)
	if kind == pacman.FileInvalid {
		http.NotFound(w, r)
		return
	}

	arch, ok := archOf(w, r)
	if !ok {
		return
	}

	repo := h.resolveRepo(w, r)
	if repo == nil {
		return
	}

	switch kind {
	case pacman.FileDatabase:
		h.serveDatabase(w, r, repo, arch, doc, false)
	case pacman.FileDatabaseSig:
		h.serveDatabase(w, r, repo, arch, doc, true)
	case pacman.FilePackageSig:
		h.servePackageSig(w, r, repo, arch, strings.TrimSuffix(filename, ".sig"))
	case pacman.FilePackage, pacman.FileInvalid:
		h.servePackage(w, r, repo, arch, filename)
	}
}

// serveDatabase serves a generated database or its signature. The ETag is the
// digest of the generated blob; Last-Modified is when it was generated, which
// is what pacman's If-Modified-Since asks about.
func (h *HTTPHandler) serveDatabase(w http.ResponseWriter, r *http.Request, repo *models.Repository, arch, doc string, sig bool) {
	path := "os/" + arch + "/" + doc

	contentType := "application/gzip"
	if sig {
		path += ".sig"
		contentType = "application/pgp-signature"
	}

	served := base.ServeRepoMetadata(w, r, h.Log, h.DB, h.BlobStore, repo, path,
		base.BlobOptions{ContentType: contentType, MaxAge: databaseMaxAge, LastModified: true})
	if !served {
		// Not generated: no package for this architecture yet, or the worker
		// has not run since the first upload.
		http.NotFound(w, r)
	}
}

// lookup returns the live package a request path names, or nil. An "any"
// package is reachable under every architecture directory.
func (h *HTTPHandler) lookup(w http.ResponseWriter, r *http.Request, repoID, arch, filename string) (*models.PacmanPackage, bool) {
	pkg, err := h.DB.GetPacmanPackageByFilename(r.Context(), repoID, filename)
	if err != nil {
		h.Log.Errorw("failed to get pacman package", "filename", filename, "error", err)
		http.Error(w, "internal error", http.StatusInternalServerError)

		return nil, false
	}

	if pkg == nil || (pkg.Arch != pacman.ArchAny && pkg.Arch != arch) {
		http.NotFound(w, r)
		return nil, false
	}

	return pkg, true
}

func (h *HTTPHandler) servePackageSig(w http.ResponseWriter, r *http.Request, repo *models.Repository, arch, filename string) {
	pkg, ok := h.lookup(w, r, repo.ID, arch, filename)
	if !ok {
		return
	}

	sig, err := base64.StdEncoding.DecodeString(pkg.Signature)
	if err != nil || len(sig) == 0 {
		// Unsigned, or not signed by the metadata worker yet.
		http.NotFound(w, r)
		return
	}

	if base.Revalidate(w, r, repo.Public, `"`+pkg.SHA256[:32]+`-`+pkg.SignatureSource+`-`+pkg.SignatureKey+`"`, databaseMaxAge) {
		return
	}

	w.Header().Set("Content-Type", "application/pgp-signature")
	_, _ = w.Write(sig)
}

func (h *HTTPHandler) servePackage(w http.ResponseWriter, r *http.Request, repo *models.Repository, arch, filename string) {
	pkg, ok := h.lookup(w, r, repo.ID, arch, filename)
	if !ok {
		return
	}

	if h.DenyIfQuarantined(w, r, repo.ID, quarantine.PathKeys(pkg.ID, "os/"+arch+"/"+filename, filename, r.URL.Path)...) {
		return
	}

	if base.Revalidate(w, r, repo.Public, `"`+pkg.SHA256+`"`, packageMaxAge) {
		return
	}

	if h.TryPresign(w, r, presign.Blob{
		SHA256: pkg.BlobKey, Size: pkg.SizeBytes, Filename: filename, ContentType: "application/octet-stream", Repository: repo,
	}) {
		return
	}

	blob, err := h.BlobStore.Get(r.Context(), pkg.BlobKey)
	if err != nil {
		h.Log.Errorw("failed to get pacman blob", "key", pkg.BlobKey, "error", err)
		http.Error(w, "internal error", http.StatusInternalServerError)

		return
	}
	defer base.CloseLog(blob, h.Log)

	h.writePackage(w, r, blob, pkg.SizeBytes)
}
